Import ListNotations.
Local Open Scope Z_scope.

(* [comment removed for export] *)
Definition cvS (i : Z) : Z := bv_unsigned (Z_to_bv 32 (fst (fp_of_int (fp_format FMT_S) RNE true 32 i))).

Definition flt_rng (n : nat) : list Z := map Z.of_nat (seq 0 n).
Definition flt_chk (n : nat) : bool :=
  let cs := map (fun i => (i, cvS i)) (flt_rng n) in
  forallb (fun a => forallb (fun b => Bool.eqb (fst (fp_lt (fp_format FMT_S) (snd a) (snd b))) (fst a <? fst b)) cs) cs.

